<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(is_file(__DIR__.'/app/access_control_v1300.php'))require_once __DIR__.'/app/access_control_v1300.php';require_once __DIR__.'/app/lms_v1360.php';if(!sk1360_enabled()){http_response_code(503);exit('Education Network is temporarily unavailable.');}$msg='';$err='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{$msg=sk1360_post_action('public');}catch(Throwable $e){$err=$e->getMessage();}}$slug=trim((string)($_GET['course']??''));$course=$slug!==''?sk1360_course_by_slug($slug):null;$csrf=sk1360_csrf();sk1360_lms_shell($course?$course['title']:'Education Network','public');if($course):$teachers=sk1360_course_teachers((int)$course['id']);$sections=sk1360_course_sections((int)$course['id'],true);$en=sk1360_uid()?sk1360_enrollment((int)$course['id']):null;?><section class="public-course-hero"><div><a class="back" href="/education-network.php">← All Courses</a><span class="eyebrow"><?=sk1360_h($course['category'])?> · <?=sk1360_h($course['level'])?></span><h1><?=sk1360_h($course['title'])?></h1><p><?=sk1360_h($course['summary'])?></p><div class="course-meta"><span><?=sk1360_h($course['language'])?></span><span><?=sk1360_h($course['institute_name']??'Independent')?></span><span><?=count($teachers)?> teacher<?=count($teachers)===1?'':'s'?></span><span><?=count($sections)?> sections</span></div></div><aside><b><?=((float)$course['price']>0)?sk1360_h($course['currency']).' '.number_format((float)$course['price'],2):'Free'?></b><?php if($en):?><a class="btn" href="/student/lms-course.php?id=<?=$course['id']?>">Go to Course</a><small><?=sk1360_h($en['status'])?> · <?=$en['progress_percent']?>%</small><?php elseif($course['enrollment_mode']==='closed'):?><span class="closed">Enrollment closed</span><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1360_h($csrf)?>"><input type="hidden" name="action" value="self.enroll"><input type="hidden" name="course_id" value="<?=$course['id']?>"><?php if(sk1360_uid()):?><button>Enroll Now</button><?php else:?><a class="btn" href="/login.php?return=<?=urlencode('/education-network.php?course='.$course['slug'])?>">Sign in to Enroll</a><?php endif;?></form><?php endif;?></aside></section><?php if($msg):?><div class="lms-alert ok"><?=sk1360_h($msg)?></div><?php endif;?><?php if($err):?><div class="lms-alert err"><?=sk1360_h($err)?></div><?php endif;?><div class="public-course-layout"><section class="portal-panel"><h2>About this Course</h2><p><?=nl2br(sk1360_h($course['description']?:$course['summary']))?></p><h2>Teaching Team</h2><div class="teacher-strip"><?php foreach($teachers as $t):?><div><span class="avatar">T</span><p><b><?=sk1360_h($t['display_name'])?></b><small><?=sk1360_h($t['teaching_role'])?></small></p></div><?php endforeach;?></div></section><section class="portal-panel"><h2>Curriculum</h2><div class="curriculum"><?php foreach($sections as $s):?><article><h3><?=sk1360_h($s['title'])?><small><?=count($s['lessons'])?> lessons</small></h3><?php foreach($s['lessons'] as $l):?><div class="lesson-row"><span><?=sk1360_h($l['lesson_type'])?></span><b><?=sk1360_h($l['title'])?></b><small><?=$l['duration_minutes']?> min <?=$l['is_preview']?'· preview':''?></small></div><?php endforeach;?></article><?php endforeach;?></div></section></div><?php else:$courses=sk1360_courses(true);?><section class="catalog-hero"><span class="eyebrow">▤ SHAHKOTPK EDUCATION NETWORK</span><h1>Learn. Teach. Grow.</h1><p>A complete multi-teaching learning network for local institutes, teachers and students.</p><div class="catalog-actions"><?php if(sk1360_uid()):?><a class="btn" href="/student/lms.php">My Learning</a><?php if(sk1360_teacher()||sk1360_admin()):?><a class="btn secondary" href="/teacher/lms.php">Teacher Portal</a><?php endif;?><?php else:?><a class="btn" href="/login.php">Sign in</a><?php endif;?></div></section><section class="catalog-section"><div class="section-head"><div><span class="eyebrow">COURSE CATALOG</span><h2>Published Courses</h2></div><input id="lms-course-search" type="search" placeholder="Search courses…"></div><div class="catalog-grid" id="lms-course-grid"><?php foreach($courses as $c):?><article class="course-card" data-search="<?=sk1360_h(strtolower($c['title'].' '.$c['category'].' '.$c['summary']))?>"><span class="course-state"><?=sk1360_h($c['category']?:'Course')?></span><h2><?=sk1360_h($c['title'])?></h2><p><?=sk1360_h($c['summary'])?></p><small><?=sk1360_h($c['level'])?> · <?=sk1360_h($c['language'])?> · <?=sk1360_h($c['institute_name']??'Independent')?></small><a class="btn" href="/education-network.php?course=<?=urlencode($c['slug'])?>">View Course</a></article><?php endforeach;?></div></section><?php endif;sk1360_lms_end();
